mapper.select:
SELECT CURRENCY
  FROM SYM0YA
 WHERE CORP_GR = #{corpGr}
   AND JM_CD   = #{jmCd}
   AND ROWNUM  = 1

SELECT CURRENCY
  FROM SYX2MM
 WHERE CORP_GR = #{corpGr}
   AND TRUSTEE = #{trustee}
   AND ROWNUM  = 1

SELECT JM_CD
  FROM SYM0YA
 WHERE CORP_GR   = #{corpGr}
   AND CURRENCY  = #{currency}
   AND GYULJE_JM = 'Y'
   AND ROWNUM    = 1

SELECT NVL(MAX(TR_SEQ), 0)
  FROM SYT0YS
 WHERE CORP_GR = #{corpGr}
   AND YMD     = TO_DATE(REPLACE(#{ymd}, '-', ''), 'YYYYMMDD')

   AND FUND_CD = #{fundCd}

mapper.update:
UPDATE SYT0YS
   SET FUND_CD         = #{fundCd, jdbcType=VARCHAR}
     , TR_CO_CD        = NVL(#{trCoCd, jdbcType=VARCHAR}, TR_CO_CD)
     , TRUSTEE         = #{trustee, jdbcType=VARCHAR}
     , JM_CD           = #{yjCd, jdbcType=VARCHAR}
     , CURRENCY        = #{currency, jdbcType=VARCHAR}
     , GYULJE_YMD      = TO_DATE(REPLACE(#{gyuljeYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
     , GYULJE_AEK      = NVL(#{gyuljeAek, jdbcType=NUMERIC}, 0)
     , WON_GYULJE_AEK  = NVL(#{wonGyuljeAek, jdbcType=NUMERIC}, 0)
     , GYULJE_GB       = NVL(#{gyuljeGb, jdbcType=VARCHAR}, 'Y')
     , GYULJE_JM_CD    = #{gyuljeJmCd, jdbcType=VARCHAR}
     , WON_HWAN_CHA    = #{wonHwanCha, jdbcType=NUMERIC}
     , SURY_AEK        = NVL(#{suryAek, jdbcType=NUMERIC}, 0)
     , FCUR_GYULJE_AEK = #{fcurGyuljeAek, jdbcType=NUMERIC}
     , FCUR_HWAN_CHA   = #{syt0ysFcurHwanCha, jdbcType=NUMERIC}
     , BUNHAL_AEK      = #{bunhalAek, jdbcType=NUMERIC}
 WHERE CORP_GR  = #{corpGr, jdbcType=VARCHAR}
   AND YMD      = TO_DATE(REPLACE(#{ymd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_YMD   = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD    = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD  = NVL(#{origFundCd, jdbcType=VARCHAR}, #{fundCd, jdbcType=VARCHAR})
   AND TR_CO_CD = NVL(#{origTrCoCd, jdbcType=VARCHAR}, NVL(#{trCoCd, jdbcType=VARCHAR}, TR_CO_CD))
   AND TRUSTEE  = NVL(#{origTrustee, jdbcType=VARCHAR}, #{trustee, jdbcType=VARCHAR})
   AND JM_CD    = NVL(#{origYjCd, jdbcType=VARCHAR}, #{yjCd, jdbcType=VARCHAR})
   AND TR_SEQ   = #{trSeq, jdbcType=NUMERIC}
   AND BS_TYPE  = #{bsType, jdbcType=NUMERIC}

mapper.delete:
