 WHERE CORP_GR  = #{corpGr, jdbcType=VARCHAR}
   AND YMD      = TO_DATE(REPLACE(#{ymd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_YMD   = TO_DATE(REPLACE(#{trYmd, jdbcType=VARCHAR}, '-', ''), 'YYYYMMDD')
   AND TR_CD    = #{trCd, jdbcType=VARCHAR}
   AND FUND_CD  = NVL(#{origFundCd, jdbcType=VARCHAR}, #{fundCd, jdbcType=VARCHAR})
   AND TR_CO_CD = NVL(#{origTrCoCd, jdbcType=VARCHAR}, NVL(#{trCoCd, jdbcType=VARCHAR}, TR_CO_CD))
   AND TRUSTEE  = NVL(#{origTrustee, jdbcType=VARCHAR}, #{trustee, jdbcType=VARCHAR})
   AND JM_CD    = NVL(#{origYjCd, jdbcType=VARCHAR}, #{yjCd, jdbcType=VARCHAR})
   AND TR_SEQ   = #{trSeq, jdbcType=NUMERIC}
   AND BS_TYPE  = #{bsType, jdbcType=NUMERIC}
